                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: i * 0.1 }}
                        key={i} 
                        className="p-8 bg-gray-50/50 rounded-[2.5rem] border border-gray-100 hover:bg-white hover:shadow-medium hover:border-primary/20 transition-all duration-500 group"
                      >
                        <h4 className="font-black text-dark text-lg mb-4 flex items-center gap-4 group-hover:text-primary transition-colors">
                          <span className="w-3 h-3 rounded-full bg-primary/20 group-hover:bg-primary transition-colors" />
                          {faq.q}
                        </h4>
                        <p className="text-gray-500 leading-relaxed font-medium pl-7">{faq.a}</p>
                      </motion.div>
                    ))}
                  </div>
                )}

                {activeTab === 'delivery-info' && (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {content[activeTab].details.map((detail, i) => (
                      <motion.div 
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: i * 0.1 }}
                        key={i} 
                        className="p-10 bg-orange-50/30 rounded-[3rem] border border-orange-100/50 hover:bg-white hover:shadow-medium transition-all duration-500"
                      >
                        <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center text-primary shadow-soft mb-8">
                          <FiTruck size={28} />
                        </div>
                        <h4 className="font-black text-xl text-dark mb-3 tracking-tight">{detail.title}</h4>
                        <p className="text-gray-500 leading-relaxed font-medium">{detail.desc}</p>
                      </motion.div>
                    ))}
                  </div>
                )}

                {['terms', 'privacy', 'refund'].includes(activeTab) && (
                  <div className="space-y-12">
                    {content[activeTab].sections.map((section, i) => (
                      <motion.div 
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: i * 0.1 }}
                        key={i} 
                        className="relative pl-12"
                      >
                        <div className="absolute left-0 top-0 text-5xl font-black text-primary/5 select-none leading-none">
                          0{i + 1}
                        </div>
                        <div className="absolute left-4 top-8 bottom-0 w-0.5 bg-gradient-to-b from-primary/40 via-primary/5 to-transparent rounded-full" />

                        <h4 className="text-xl font-black text-dark mb-4 uppercase tracking-wider italic font-serif">
                          {section.h}
                        </h4>
                        <p className="text-gray-500 text-lg leading-relaxed font-medium max-w-3xl">
                          {section.p}
                        </p>
                      </motion.div>
                    ))}
                    <div className="pt-12 border-t border-gray-100 mt-16 flex items-center justify-between">
                      <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest italic">
                        Luxury Experience Protocol — Last Updated May 2026
                      </p>
                      <div className="flex gap-2">
                        <div className="w-2 h-2 rounded-full bg-primary/20" />
                        <div className="w-2 h-2 rounded-full bg-primary/40" />
                        <div className="w-2 h-2 rounded-full bg-primary/60" />
                      </div>
                    </div>
                  </div>
                )}
              </motion.div>
            </AnimatePresence>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  )
}

export default Support

import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useSelector } from 'react-redux'
import { motion, AnimatePresence } from 'framer-motion'
import toast from 'react-hot-toast'
import { 
  FiPieChart, FiUsers, FiShoppingBag, FiDatabase, 
  FiTruck, FiDollarSign, FiMenu, FiHome, FiLogOut,
  FiTrendingUp, FiAlertCircle, FiCheckCircle, FiXCircle
} from 'react-icons/fi'
import axiosInstance from '../../api/axiosInstance'
import AdminUsers from './AdminUsers'
import AdminOrders from './AdminOrders'
import AdminInventory from './AdminInventory'
import AdminVendors from './AdminVendors'
import AdminPayments from './AdminPayments'

const StatCard = ({ icon: Icon, label, value, color, sub, trend }) => (
  <motion.div
    whileHover={{ y: -5, boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1)' }}
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    className="bg-white rounded-3xl p-6 shadow-soft border border-gray-50 relative overflow-hidden group"
  >
    <div className={`absolute top-0 right-0 w-24 h-24 -mr-8 -mt-8 rounded-full opacity-10 transition-transform group-hover:scale-150 duration-500 ${color.split(' ')[0]}`} />
    
    <div className="flex items-center justify-between mb-4 relative z-10">
      <div className={`p-3 rounded-2xl ${color}`}>
        <Icon size={24} />
      </div>
      <span className="text-[10px] font-bold uppercase tracking-wider text-gray-400 bg-gray-50 px-2 py-1 rounded-lg">
        {sub}
      </span>
    </div>
    
    <div className="relative z-10">
      <h3 className="text-3xl font-bold text-dark tracking-tight">{value}</h3>
      <p className="text-gray-500 text-sm font-medium mt-1">{label}</p>
      {trend && (
        <div className="flex items-center gap-1 mt-3 text-green-500 text-xs font-bold">
          <FiTrendingUp />
          <span>{trend}</span>
        </div>
      )}
    </div>
  </motion.div>
)

const tabs = [
  { key: 'overview',   label: 'Overview',   icon: FiPieChart },
  { key: 'orders',     label: 'Orders',     icon: FiShoppingBag },
  { key: 'users',      label: 'Users',      icon: FiUsers },
  { key: 'inventory',  label: 'Inventory',  icon: FiDatabase },
  { key: 'vendors',    label: 'Vendors',    icon: FiTruck },
  { key: 'payments',   label: 'Payments',   icon: FiDollarSign },
]

const AdminDashboard = () => {
  const { user }            = useSelector(state => state.auth)
  const navigate            = useNavigate()
  const [activeTab, setActiveTab] = useState('overview')
  const [stats, setStats]   = useState(null)
  const [recentOrders, setRecentOrders] = useState([])
  const [lowStock, setLowStock]   = useState([])
  const [loading, setLoading]     = useState(true)
  const [sidebarOpen, setSidebarOpen] = useState(true)

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/')
      return
    }
    fetchDashboard()
  }, [user])

  const fetchDashboard = async () => {
    try {
      const res = await axiosInstance.get('/admin/dashboard')
      setStats(res.data.stats)
      setRecentOrders(res.data.recentOrders)
      setLowStock(res.data.lowStockProducts)
    } catch {
      toast.error('Failed to load dashboard')
    } finally {
      setLoading(false)
    }
  }

  const statusColor = {
    placed:           'bg-blue-50   text-blue-600 border border-blue-100',
    confirmed:        'bg-yellow-50 text-yellow-600 border border-yellow-100',
    preparing:        'bg-orange-50 text-orange-600 border border-orange-100',
    out_for_delivery: 'bg-purple-50 text-purple-600 border border-purple-100',
    delivered:        'bg-green-50  text-green-600 border border-green-100',
    cancelled:        'bg-red-50    text-red-500 border border-red-100',
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex font-poppins">

      {/* Sidebar */}
      <aside className={`${sidebarOpen ? 'w-72' : 'w-20'} bg-dark text-white transition-all duration-500 ease-in-out flex flex-col sticky top-0 h-screen z-30 shadow-hard`}>
        {/* Logo */}
        <div className="h-20 flex items-center px-6 gap-4 border-b border-gray-800/50">
          <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center shadow-glow flex-shrink-0">
            <span className="text-2xl">🍦</span>
          </div>
          {sidebarOpen && (
            <motion.span 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="font-extrabold text-xl tracking-tight bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent"
            >
              IceCream.
            </motion.span>
          )}
        </div>

        {/* Nav */}
        <nav className="flex-1 py-6 px-3 space-y-1">
          {tabs.map(tab => {
            const Icon = tab.icon
            return (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all duration-300 group ${
                  activeTab === tab.key
                    ? 'bg-primary text-white shadow-glow'
                    : 'text-gray-400 hover:bg-gray-800/50 hover:text-white'
                }`}
              >
                <Icon size={20} className={`${activeTab === tab.key ? 'scale-110' : 'group-hover:scale-110'} transition-transform duration-300`} />
                {sidebarOpen && (
                  <motion.span 
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="font-semibold text-sm"
                  >
                    {tab.label}
                  </motion.span>
                )}
              </button>
            )
          })}
        </nav>

        {/* Bottom */}
        <div className="p-4 border-t border-gray-800/50 space-y-2">
          <button
            onClick={() => navigate('/')}
            className="w-full flex items-center gap-4 px-4 py-3 text-gray-400 hover:text-white transition-all hover:bg-gray-800/50 rounded-2xl"
          >
            <FiHome size={20} />
            {sidebarOpen && <span className="text-sm font-medium">Back to Site</span>}
          </button>
          <button
             onClick={() => {
               localStorage.removeItem('accessToken')
               navigate('/login')
             }}
             className="w-full flex items-center gap-4 px-4 py-3 text-red-400 hover:text-red-300 transition-all hover:bg-red-500/10 rounded-2xl"
          >
            <FiLogOut size={20} />
            {sidebarOpen && <span className="text-sm font-medium">Logout</span>}
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-auto h-screen custom-scrollbar">

        {/* Top Bar */}
        <div className="bg-white/80 backdrop-blur-md border-b border-gray-100 px-8 h-20 flex items-center justify-between sticky top-0 z-20">
          <div className="flex items-center gap-6">
            <button
              onClick={() => setSidebarOpen(!sidebarOpen)}
              className="p-2.5 bg-gray-50 rounded-xl text-gray-500 hover:text-primary transition-all hover:bg-orange-50 active:scale-95 shadow-sm"
            >
              <FiMenu size={20} />
            </button>
            <div>
              <h1 className="font-bold text-dark text-xl tracking-tight">
                {tabs.find(t => t.key === activeTab)?.label} Dashboard
              </h1>
              <p className="text-xs text-gray-400 font-medium hidden sm:block">Welcome back, {user?.name}</p>
            </div>
          </div>
          
          <div 
            onClick={() => navigate('/profile')}
            className="flex items-center gap-4 bg-gray-50 p-1.5 pr-4 rounded-2xl border border-gray-100 cursor-pointer hover:border-primary/30 transition-all active:scale-95 group"
          >
            <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center text-white font-bold text-lg shadow-glow group-hover:scale-110 transition-transform overflow-hidden">
              {user?.profileImage ? (
                <img src={user.profileImage} alt="Avatar" className="w-full h-full object-cover" />
              ) : (
                user?.name?.[0]?.toUpperCase()
              )}
            </div>
            <div className="text-left hidden md:block">
              <p className="text-sm font-bold text-dark leading-none">{user?.name}</p>
              <p className="text-[10px] font-bold text-primary uppercase mt-1 tracking-wider">Super Admin</p>
            </div>
          </div>
        </div>

        <div className="p-8 max-w-7xl mx-auto">
          <AnimatePresence mode="wait">
            <motion.div
              key={activeTab}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.3, ease: 'easeOut' }}
            >
              {/* OVERVIEW TAB */}
              {activeTab === 'overview' && (
                <div className="space-y-8">
                  {loading ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                      {[...Array(8)].map((_, i) => (
                        <div key={i} className="bg-white rounded-3xl h-36 animate-pulse border border-gray-50" />
                      ))}
                    </div>
                  ) : (
                    <>
                      {/* Stat Cards */}
                      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                        <StatCard icon={FiUsers} label="Total Users" value={stats?.totalUsers} color="bg-blue-500 text-white" sub="Users" trend="+12% this month" />
                        <StatCard icon={FiDatabase} label="Total Products" value={stats?.totalProducts} color="bg-orange-500 text-white" sub="Products" />
                        <StatCard icon={FiShoppingBag} label="Total Orders" value={stats?.totalOrders} color="bg-purple-500 text-white" sub="Orders" trend="+24% today" />
                        <StatCard icon={FiDollarSign} label="Total Revenue" value={`₹${stats?.totalRevenue?.toLocaleString()}`} color="bg-green-500 text-white" sub="Revenue" trend="+8% growth" />
                        <StatCard icon={FiAlertCircle} label="Pending Orders" value={stats?.pendingOrders} color="bg-yellow-500 text-white" sub="Pending" />
                        <StatCard icon={FiCheckCircle} label="Delivered" value={stats?.deliveredOrders} color="bg-emerald-500 text-white" sub="Completed" />
                        <StatCard icon={FiTruck} label="Total Vendors" value={stats?.totalVendors} color="bg-indigo-500 text-white" sub="Vendors" />
                        <StatCard icon={FiXCircle} label="Cancelled" value={stats?.cancelledOrders} color="bg-red-500 text-white" sub="Lost" />
                      </div>

                      {/* Recent Orders + Low Stock */}
                      <div className="grid grid-cols-1 lg:grid-cols-7 gap-8">

                        {/* Recent Orders */}
                        <div className="lg:col-span-4 bg-white rounded-3xl p-8 shadow-soft border border-gray-50">
                          <div className="flex items-center justify-between mb-8">
                            <div>
                              <h3 className="font-bold text-dark text-lg">Recent Transactions</h3>
                              <p className="text-xs text-gray-400 font-medium">Latest customer activity</p>
                            </div>
                            <button
                              onClick={() => setActiveTab('orders')}
                              className="px-4 py-2 bg-gray-50 text-primary text-xs font-bold rounded-xl hover:bg-orange-50 transition-colors border border-gray-100"
                            >
                              View All
                            </button>
                          </div>
                          <div className="space-y-4">
                            {recentOrders.length === 0 ? (
                              <div className="text-center py-12">
                                <p className="text-4xl grayscale opacity-20 mb-3">🛒</p>
                                <p className="text-gray-400 text-sm font-medium">No recent orders</p>
                              </div>
                            ) : recentOrders.map((order, i) => (
                              <motion.div 
                                initial={{ opacity: 0, x: -20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: i * 0.1 }}
                                key={order._id} 
                                className="flex items-center justify-between p-4 rounded-2xl bg-gray-50/50 border border-transparent hover:border-gray-100 hover:bg-white transition-all group"
                              >
                                <div className="flex items-center gap-4">
                                  <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-sm text-lg font-bold group-hover:scale-110 transition-transform">
                                    {order.user?.name?.[0]}
                                  </div>
                                  <div>
                                    <p className="font-bold text-dark text-sm">
                                      #{order._id.slice(-6).toUpperCase()}
                                    </p>
                                    <p className="text-xs text-gray-500 font-medium">{order.user?.name}</p>
                                  </div>
                                </div>
                                <div className="text-right">
                                  <p className="font-extrabold text-dark text-sm">₹{order.totalAmount}</p>
                                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-lg uppercase tracking-tight mt-1 inline-block ${statusColor[order.orderStatus]}`}>
                                    {order.orderStatus.replace('_', ' ')}
                                  </span>
                                </div>
                              </motion.div>
                            ))}
                          </div>
                        </div>

                        {/* Low Stock */}
                        <div className="lg:col-span-3 bg-white rounded-3xl p-8 shadow-soft border border-gray-50">
                          <div className="flex items-center justify-between mb-8">
                            <div>
                              <h3 className="font-bold text-dark text-lg">Inventory Alerts</h3>
                              <p className="text-xs text-gray-400 font-medium">Critical stock levels</p>
                            </div>
                            <button
                              onClick={() => setActiveTab('inventory')}
                              className="px-4 py-2 bg-red-50 text-red-500 text-xs font-bold rounded-xl hover:bg-red-100 transition-colors border border-red-50"
                            >
                              Manage
                            </button>
                          </div>
                          <div className="space-y-4">
                            {lowStock.length === 0 ? (
                              <div className="text-center py-12 bg-green-50/30 rounded-3xl border border-dashed border-green-200">
                                <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4 text-2xl">✅</div>
                                <p className="text-green-600 font-bold text-sm">Inventory healthy!</p>
                                <p className="text-green-500/70 text-xs mt-1">All products are well stocked</p>
                              </div>
                            ) : lowStock.map((product, i) => (
                              <motion.div 
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                transition={{ delay: i * 0.1 }}
                                key={product._id} 
                                className="flex items-center justify-between p-4 rounded-2xl bg-white border border-gray-100 hover:shadow-soft transition-all"
                              >
                                <div className="flex items-center gap-3">
                                  <div className="w-10 h-10 bg-orange-50 rounded-xl flex items-center justify-center text-xl">🍦</div>
                                  <div>
                                    <p className="font-bold text-dark text-sm line-clamp-1">{product.name}</p>
                                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">
                                      {product.inStock ? 'Available' : 'Sold Out'}
                                    </p>
                                  </div>
                                </div>
                                <div className={`px-3 py-1 rounded-xl text-center border ${
                                  product.stockQuantity < 5
                                    ? 'bg-red-50 text-red-500 border-red-100'
                                    : 'bg-yellow-50 text-yellow-600 border-yellow-100'
                                }`}>
                                  <p className="text-xs font-bold leading-tight">{product.stockQuantity}</p>
                                  <p className="text-[8px] font-black uppercase tracking-tighter">Left</p>
                                </div>
                              </motion.div>
                            ))}
                          </div>
                        </div>
                      </div>
                    </>
                  )}
                </div>
              )}

              {/* Other Tabs */}
              {activeTab === 'orders'    && <AdminOrders />}
              {activeTab === 'users'     && <AdminUsers />}
              {activeTab === 'inventory' && <AdminInventory />}
              {activeTab === 'vendors'   && <AdminVendors />}
              {activeTab === 'payments'  && <AdminPayments />}
            </motion.div>
          </AnimatePresence>
        </div>
      </main>
    </div>
  )
}

export default AdminDashboard

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FiRefreshCw, FiEdit3, FiPackage, FiSave, FiX, FiCheckCircle, FiAlertTriangle } from 'react-icons/fi'
import toast from 'react-hot-toast'
import axiosInstance from '../../api/axiosInstance'

const AdminInventory = () => {
  const [products, setProducts] = useState([])
  const [loading,  setLoading]  = useState(true)
  const [editing,  setEditing]  = useState(null)
  const [form,     setForm]     = useState({ stockQuantity: 0, inStock: true })

  useEffect(() => { fetchInventory() }, [])

  const fetchInventory = async () => {
    setLoading(true)
    try {
      const res = await axiosInstance.get('/admin/inventory')
      setProducts(res.data.products)
    } catch {
      toast.error('Failed to load inventory')
    } finally {
      setLoading(false)
    }
  }

  const handleEdit = (product) => {
    setEditing(product._id)
    setForm({ stockQuantity: product.stockQuantity, inStock: product.inStock })
  }

  const handleUpdate = async (productId) => {
    try {
      await axiosInstance.put(`/admin/inventory/${productId}`, form)
      toast.success('Inventory updated!')
      setEditing(null)
      fetchInventory()
    } catch {
      toast.error('Failed to update')
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="bg-white px-4 py-2 rounded-xl shadow-soft border border-gray-50 flex items-center gap-2">
          <FiPackage className="text-primary" />
          <p className="text-sm font-bold text-dark">{products.length} <span className="text-gray-400 font-medium">Products</span></p>
        </div>
        <button 
          onClick={fetchInventory} 
          className="flex items-center gap-2 px-4 py-2 bg-white text-gray-500 hover:text-primary rounded-xl shadow-soft border border-gray-50 transition-all active:scale-95 text-sm font-bold"
        >
          <FiRefreshCw className={loading ? 'animate-spin' : ''} />
          Refresh
        </button>
      </div>

      {loading ? (
        <div className="space-y-4">
          {[1,2,3,4].map(i => <div key={i} className="bg-white rounded-3xl h-20 animate-pulse border border-gray-50 shadow-soft" />)}
        </div>
      ) : (
        <div className="bg-white rounded-3xl shadow-soft border border-gray-50 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Product</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Category</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Stock Level</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Status</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Vendor</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px] text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {products.map((product, i) => (
                  <motion.tr 
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.05 }}
                    key={product._id} 
                    className="hover:bg-gray-50/50 transition-colors group"
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-orange-50 rounded-xl flex items-center justify-center text-xl shadow-sm border border-orange-100 group-hover:scale-110 transition-transform">
                          🍦
                        </div>
                        <span className="font-bold text-dark">{product.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">
                        {product.category}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      {editing === product._id ? (
                        <input
                          type="number"
                          value={form.stockQuantity}
                          onChange={e => setForm({ ...form, stockQuantity: Number(e.target.value) })}
                          className="w-24 bg-gray-50 border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary font-bold transition-all"
                        />
                      ) : (
                        <div className="flex items-center gap-2">
                          <span className={`text-base font-black ${product.stockQuantity < 10 ? 'text-red-500' : 'text-dark'}`}>
                            {product.stockQuantity}
                          </span>
                          {product.stockQuantity < 10 && <FiAlertTriangle className="text-red-500 animate-pulse" />}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      {editing === product._id ? (
                        <select
                          value={form.inStock}
                          onChange={e => setForm({ ...form, inStock: e.target.value === 'true' })}
                          className="bg-gray-50 border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary font-bold transition-all cursor-pointer"
                        >
                          <option value="true">In Stock</option>
                          <option value="false">Out of Stock</option>
                        </select>
                      ) : (
                        <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${product.inStock ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-red-50 text-red-600 border border-red-100'}`}>
                          {product.inStock ? <FiCheckCircle /> : <FiX />}
                          {product.inStock ? 'In Stock' : 'Sold Out'}
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-4 text-gray-400 font-medium">
                      <div className="text-[11px] bg-indigo-50/50 text-indigo-600 px-2 py-1 rounded-lg border border-indigo-100 inline-block">
                        {product.vendor?.storeName || 'Store Admin'}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {editing === product._id ? (
                        <div className="flex justify-end gap-2">
                          <button
                            onClick={() => handleUpdate(product._id)}
                            className="p-2 bg-primary text-white rounded-lg hover:bg-orange-600 shadow-glow transition-all active:scale-90"
                            title="Save Changes"
                          >
                            <FiSave size={16} />
                          </button>
                          <button
                            onClick={() => setEditing(null)}
                            className="p-2 bg-gray-100 text-gray-500 rounded-lg hover:bg-gray-200 transition-all active:scale-90"
                            title="Cancel"
                          >
                            <FiX size={16} />
                          </button>
                        </div>
                      ) : (
                        <button
                          onClick={() => handleEdit(product)}
                          className="p-2 text-gray-300 hover:text-primary hover:bg-orange-50 rounded-lg transition-all active:scale-90"
                          title="Edit Stock"
                        >
                          <FiEdit3 size={16} />
                        </button>
                      )}
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
          {products.length === 0 && (
            <div className="text-center py-20 bg-gray-50/30">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
                <FiPackage size={40} />
              </div>
              <h4 className="text-dark font-bold">No products found</h4>
              <p className="text-gray-400 text-xs mt-1">Inventory is currently empty</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default AdminInventory

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FiShoppingBag, FiUser, FiClock, FiCheckCircle, FiTruck, FiXCircle, FiMoreVertical } from 'react-icons/fi'
import toast from 'react-hot-toast'
import axiosInstance from '../../api/axiosInstance'

const statusColors = {
  placed:           'bg-blue-50 text-blue-600 border-blue-100',
  confirmed:        'bg-yellow-50 text-yellow-600 border-yellow-100',
  preparing:        'bg-orange-50 text-orange-600 border-orange-100',
  out_for_delivery: 'bg-purple-50 text-purple-600 border-purple-100',
  delivered:        'bg-green-50 text-green-600 border-green-100',
  cancelled:        'bg-red-50 text-red-500 border-red-100',
}

const AdminOrders = () => {
  const [orders,  setOrders]  = useState([])
  const [loading, setLoading] = useState(true)
  const [filter,  setFilter]  = useState('')
  const [updating, setUpdating] = useState(null)

  useEffect(() => { fetchOrders() }, [filter])

  const fetchOrders = async () => {
    setLoading(true)
    try {
      const params = filter ? `?status=${filter}` : ''
      const res    = await axiosInstance.get(`/orders/all${params}`)
      setOrders(res.data.orders)
    } catch {
      toast.error('Failed to load orders')
    } finally {
      setLoading(false)
    }
  }

  const updateStatus = async (orderId, status) => {
    setUpdating(orderId)
    try {
      await axiosInstance.put(`/orders/${orderId}/status`, { status })
      toast.success(`Order updated to ${status}`)
      fetchOrders()
    } catch {
      toast.error('Failed to update order')
    } finally {
      setUpdating(null)
    }
  }

  const formatDate = d => new Date(d).toLocaleDateString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric'
  })

  return (
    <div className="space-y-6">
      {/* Filters */}
      <div className="flex gap-2 flex-wrap bg-white p-2 rounded-2xl shadow-soft border border-gray-50">
        {['', 'placed', 'confirmed', 'preparing', 'out_for_delivery', 'delivered', 'cancelled'].map(s => (
          <button key={s}
            onClick={() => setFilter(s)}
            className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
              filter === s 
                ? 'bg-primary text-white shadow-glow' 
                : 'bg-transparent text-gray-400 hover:text-dark hover:bg-gray-50'
            }`}
          >
            {s === '' ? 'All Orders' : s.replace('_', ' ')}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="space-y-4">
          {[1,2,3,4].map(i => <div key={i} className="bg-white rounded-3xl h-24 animate-pulse border border-gray-50 shadow-soft" />)}
        </div>
      ) : (
        <div className="bg-white rounded-3xl shadow-soft border border-gray-50 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Order Details</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Customer</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Total Amount</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Status</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Date</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px] text-right">Update Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {orders.map((order, i) => (
                  <motion.tr 
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.05 }}
                    key={order._id} 
                    className="hover:bg-gray-50/50 transition-colors group"
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center text-blue-600 border border-blue-100">
                          <FiShoppingBag size={20} />
                        </div>
                        <div>
                          <p className="font-black text-dark tracking-tighter">#{order._id.slice(-8).toUpperCase()}</p>
                          <p className="text-[10px] text-gray-400 font-bold">{order.items?.length} Items Ordered</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <div className="w-6 h-6 bg-gray-100 rounded-full flex items-center justify-center text-[10px] font-bold text-gray-500">
                          {order.user?.name?.[0]}
                        </div>
                        <div>
                          <p className="font-bold text-dark text-xs">{order.user?.name}</p>
                          <p className="text-[10px] text-gray-400 font-medium line-clamp-1">{order.user?.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 font-extrabold text-primary">₹{order.totalAmount}</td>
                    <td className="px-6 py-4">
                      <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border ${statusColors[order.orderStatus]}`}>
                        {order.orderStatus === 'delivered' ? <FiCheckCircle /> : <FiClock />}
                        {order.orderStatus?.replace('_', ' ')}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-gray-500 font-bold text-[11px]">{formatDate(order.createdAt)}</p>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <select
                        onChange={e => updateStatus(order._id, e.target.value)}
                        value={order.orderStatus}
                        disabled={updating === order._id}
                        className="bg-gray-50 border border-gray-200 rounded-xl px-3 py-1.5 text-[10px] font-bold uppercase tracking-widest focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary cursor-pointer transition-all disabled:opacity-50"
                      >
                        {['placed','confirmed','preparing','out_for_delivery','delivered','cancelled'].map(s => (
                          <option key={s} value={s}>{s.replace('_',' ')}</option>
                        ))}
                      </select>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
          {orders.length === 0 && (
            <div className="text-center py-20 bg-gray-50/30">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
                <FiShoppingBag size={40} />
              </div>
              <h4 className="text-dark font-bold">No orders found</h4>
              <p className="text-gray-400 text-xs mt-1">Order list is currently empty</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default AdminOrders

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FiDollarSign, FiUser, FiCreditCard, FiCheckCircle, FiClock, FiActivity, FiArrowUpRight } from 'react-icons/fi'
import toast from 'react-hot-toast'
import axiosInstance from '../../api/axiosInstance'

const AdminPayments = () => {
  const [orders,   setOrders]   = useState([])
  const [loading,  setLoading]  = useState(true)
  const [revenue,  setRevenue]  = useState(0)
  const [filter,   setFilter]   = useState('')

  useEffect(() => { fetchPayments() }, [filter])

  const fetchPayments = async () => {
    setLoading(true)
    try {
      const params = filter ? `?paymentStatus=${filter}` : ''
      const res    = await axiosInstance.get(`/admin/payments${params}`)
      setOrders(res.data.orders)
      setRevenue(res.data.totalRevenue)
    } catch {
      toast.error('Failed to load payments')
    } finally {
      setLoading(false)
    }
  }

  const confirmCOD = async (orderId) => {
    try {
      await axiosInstance.put(`/orders/${orderId}/confirm-cod`)
      toast.success('COD payment confirmed!')
      fetchPayments()
    } catch {
      toast.error('Failed to confirm payment')
    }
  }

  const formatDate = d => new Date(d).toLocaleDateString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric'
  })

  return (
    <div className="space-y-6">
      {/* Revenue Card */}
      <motion.div 
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 rounded-3xl p-8 text-white shadow-hard relative overflow-hidden group"
      >
        <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform duration-700">
          <FiDollarSign size={120} />
        </div>
        <div className="relative z-10">
          <div className="flex items-center gap-2 mb-2">
            <div className="p-2 bg-white/20 rounded-lg backdrop-blur-md">
              <FiActivity />
            </div>
            <p className="text-white/80 text-sm font-bold uppercase tracking-widest">Total Revenue</p>
          </div>
          <div className="flex items-end gap-3">
            <p className="text-5xl font-black tracking-tighter">₹{revenue?.toLocaleString()}</p>
            <div className="flex items-center gap-1 text-green-300 text-xs font-bold mb-2 bg-white/10 px-2 py-1 rounded-lg">
              <FiArrowUpRight />
              <span>+14.2%</span>
            </div>
          </div>
          <p className="text-white/60 text-[10px] font-black uppercase tracking-widest mt-4">Verified Earnings from Delivered Orders</p>
        </div>
      </motion.div>

      {/* Filters */}
      <div className="flex gap-2 bg-white p-2 rounded-2xl shadow-soft border border-gray-50 max-w-fit">
        {[
          { val: '',        label: 'All Payments' },
          { val: 'pending', label: 'Pending' },
          { val: 'paid',    label: 'Paid' },
        ].map(f => (
          <button key={f.val}
            onClick={() => setFilter(f.val)}
            className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
              filter === f.val 
                ? 'bg-primary text-white shadow-glow' 
                : 'bg-transparent text-gray-400 hover:text-dark hover:bg-gray-50'
            }`}
          >
            {f.label}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="space-y-4">
          {[1,2,3,4].map(i => <div key={i} className="bg-white rounded-3xl h-24 animate-pulse border border-gray-50 shadow-soft" />)}
        </div>
      ) : (
        <div className="bg-white rounded-3xl shadow-soft border border-gray-50 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Reference</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Customer</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Amount</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Method</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Payment Status</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Date</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px] text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {orders.map((order, i) => (
                  <motion.tr 
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.05 }}
                    key={order._id} 
                    className="hover:bg-gray-50/50 transition-colors group"
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600 border border-indigo-100 font-black text-[10px]">
