                        </div>
                        <p className="font-black text-dark tracking-tighter uppercase">#{order._id?.slice(-8)}</p>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <div className="w-6 h-6 bg-gray-100 rounded-full flex items-center justify-center text-[10px] font-bold text-gray-500">
                          {order.user?.name?.[0]}
                        </div>
                        <div>
                          <p className="font-bold text-dark text-xs">{order.user?.name}</p>
                          <p className="text-[10px] text-gray-400 font-medium">{order.user?.phone}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 font-black text-dark italic">₹{order.totalAmount}</td>
                    <td className="px-6 py-4">
                      <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-lg text-[10px] font-black uppercase tracking-widest border border-gray-200">
                        {order.paymentMethod}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border ${
                        order.paymentStatus === 'paid'
                          ? 'bg-emerald-50 text-emerald-600 border-emerald-100'
                          : 'bg-amber-50 text-amber-600 border-amber-100'
                      }`}>
                        {order.paymentStatus === 'paid' ? <FiCheckCircle /> : <FiClock />}
                        {order.paymentStatus}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-gray-400 font-bold text-[11px]">{formatDate(order.createdAt)}</p>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {order.paymentStatus === 'pending' && order.paymentMethod === 'COD' && (
                        <button
                          onClick={() => confirmCOD(order._id)}
                          className="px-4 py-2 bg-emerald-500 text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-emerald-600 shadow-glow transition-all active:scale-95"
                        >
                          Confirm
                        </button>
                      )}
                      {order.paymentStatus === 'paid' && (
                        <div className="flex items-center justify-end gap-1 text-emerald-500 font-black text-[10px] uppercase tracking-widest">
                          <FiCheckCircle />
                          <span>Verified</span>
                        </div>
                      )}
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
          {orders.length === 0 && (
            <div className="text-center py-20 bg-gray-50/30">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
                <FiCreditCard size={40} />
              </div>
              <h4 className="text-dark font-bold">No payment records</h4>
              <p className="text-gray-400 text-xs mt-1">Transactions will appear here</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default AdminPayments

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FiSearch, FiTrash2, FiUser, FiMail, FiCalendar, FiShield, FiCheckCircle, FiX } from 'react-icons/fi'
import toast from 'react-hot-toast'
import axiosInstance from '../../api/axiosInstance'

const roleColors = {
  user:   'bg-blue-50 text-blue-600 border-blue-100',
  admin:  'bg-red-50 text-red-600 border-red-100',
  vendor: 'bg-green-50 text-green-600 border-green-100',
}

const AdminUsers = () => {
  const [users,   setUsers]   = useState([])
  const [loading, setLoading] = useState(true)
  const [search,  setSearch]  = useState('')
  const [approveModalUser, setApproveModalUser] = useState(null)
  const [deleteModalUser,  setDeleteModalUser]  = useState(null)

  const handleApproveVendor = async () => {
    if (!approveModalUser) return
    try {
      setLoading(true)
      await axiosInstance.post(`/admin/users/${approveModalUser}/send-vendor-code`)
      toast.success('Verification code sent!')
      fetchUsers()
      setApproveModalUser(null)
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to send code')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { fetchUsers() }, [])

  const fetchUsers = async () => {
    setLoading(true)
    try {
      const res = await axiosInstance.get('/admin/users')
      setUsers(res.data.users)
    } catch {
      toast.error('Failed to load users')
    } finally {
      setLoading(false)
    }
  }

  const updateRole = async (userId, role) => {
    try {
      await axiosInstance.put(`/admin/users/${userId}/role`, { role })
      toast.success('Role updated!')
      fetchUsers()
    } catch {
      toast.error('Failed to update role')
    }
  }

  const handleDeleteUser = async () => {
    if (!deleteModalUser) return
    try {
      await axiosInstance.delete(`/admin/users/${deleteModalUser}`)
      toast.success('User deleted')
      fetchUsers()
      setDeleteModalUser(null)
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to delete')
    }
  }

  const filtered = users.filter(u =>
    u.name?.toLowerCase().includes(search.toLowerCase()) ||
    u.email?.toLowerCase().includes(search.toLowerCase())
  )

  const formatDate = d => new Date(d).toLocaleDateString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric'
  })

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="relative max-w-md w-full">
          <FiSearch className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search users by name or email..."
            className="w-full bg-white border border-gray-100 rounded-2xl pl-11 pr-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all shadow-soft"
          />
        </div>
        <p className="text-sm font-medium text-gray-500 bg-white px-4 py-2 rounded-xl shadow-soft border border-gray-50">
          Total: <span className="text-dark font-bold">{users.length}</span> Users
        </p>
      </div>

      {loading ? (
        <div className="space-y-4">
          {[1,2,3,4].map(i => <div key={i} className="bg-white rounded-3xl h-20 animate-pulse border border-gray-50 shadow-soft" />)}
        </div>
      ) : (
        <div className="bg-white rounded-3xl shadow-soft border border-gray-50 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">User</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Email</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Role</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Status</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px]">Joined</th>
                  <th className="px-6 py-4 text-gray-400 font-bold uppercase tracking-wider text-[10px] text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filtered.map((user, i) => (
                  <motion.tr 
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.05 }}
                    key={user._id} 
                    className="hover:bg-gray-50/50 transition-colors group"
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-primary/10 rounded-xl flex items-center justify-center font-bold text-primary shadow-sm border border-primary/20">
                          {user.name?.[0]?.toUpperCase() || <FiUser />}
                        </div>
                        <span className="font-bold text-dark">{user.name}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 text-gray-500 font-medium">
                        <FiMail className="opacity-50" />
                        {user.email}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <select
                        value={user.role}
                        onChange={e => updateRole(user._id, e.target.value)}
                        className={`text-[10px] px-3 py-1.5 rounded-lg font-black uppercase tracking-widest border ${roleColors[user.role]} focus:outline-none cursor-pointer transition-all hover:shadow-sm`}
                      >
                        <option value="user">User</option>
                        <option value="admin">Admin</option>
                        <option value="vendor">Vendor</option>
                      </select>
                    </td>
                    <td className="px-6 py-4">
                      <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${user.isVerified ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-amber-50 text-amber-600 border border-amber-100'}`}>
                        {user.isVerified ? <FiCheckCircle /> : <FiShield />}
                        {user.isVerified ? 'Verified' : 'Pending'}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-gray-400 font-medium">
                      <div className="flex items-center gap-2 text-[11px]">
                        <FiCalendar className="opacity-50" />
                        {formatDate(user.createdAt)}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                        {user.vendorStatus === 'pending' && (
                          <button
                            onClick={() => setApproveModalUser(user._id)}
                            className="px-3 py-1.5 bg-primary text-white text-[10px] font-black uppercase tracking-widest rounded-lg hover:bg-orange-600 transition-all shadow-soft"
                          >
                            Approve Vendor
                          </button>
                        )}
                        <button
                          onClick={() => setDeleteModalUser(user._id)}
                          className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all active:scale-90"
                          title="Delete User"
                        >
                          <FiTrash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
          {filtered.length === 0 && (
            <div className="text-center py-20 bg-gray-50/30">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
                <FiUsers size={40} />
              </div>
              <h4 className="text-dark font-bold">No users found</h4>
              <p className="text-gray-400 text-xs mt-1">Try searching for something else</p>
            </div>
          )}
        </div>
      )}

      {/* Approve Vendor Modal */}
      {approveModalUser && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-[2rem] p-8 max-w-sm w-full relative shadow-2xl text-center"
          >
            <button 
              onClick={() => setApproveModalUser(null)}
              className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition-colors"
            >
              <FiX size={24} />
            </button>
            
            <div className="w-20 h-20 bg-emerald-50 rounded-full flex items-center justify-center mx-auto mb-6">
              <FiCheckCircle className="text-emerald-500" size={36} />
            </div>

            <h3 className="text-2xl font-black text-dark mb-3 italic">Approve Vendor?</h3>
            <p className="text-gray-500 text-sm font-medium mb-8">
              Are you sure you want to approve this vendor application and send the verification code?
            </p>

            <div className="flex flex-col gap-3">
              <button
                onClick={handleApproveVendor}
                disabled={loading}
                className="w-full py-4 bg-emerald-500 text-white rounded-2xl text-sm font-black uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-lg shadow-emerald-500/30 disabled:opacity-50"
              >
                {loading ? 'Approving...' : 'Yes, Approve Vendor'}
              </button>
              <button
                onClick={() => setApproveModalUser(null)}
                disabled={loading}
                className="w-full py-4 bg-gray-50 text-gray-600 rounded-2xl text-sm font-black uppercase tracking-widest hover:bg-gray-100 transition-all disabled:opacity-50"
              >
                Cancel
              </button>
            </div>
          </motion.div>
        </div>
      )}

      {/* Delete User Modal */}
      {deleteModalUser && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white rounded-[2rem] p-8 max-w-sm w-full relative shadow-2xl text-center"
          >
            <button 
              onClick={() => setDeleteModalUser(null)}
              className="absolute top-6 right-6 text-gray-400 hover:text-gray-600 transition-colors"
            >
              <FiX size={24} />
            </button>
            
            <div className="w-20 h-20 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-6">
              <FiTrash2 className="text-red-500" size={36} />
            </div>

            <h3 className="text-2xl font-black text-dark mb-3 italic">Delete User?</h3>
            <p className="text-gray-500 text-sm font-medium mb-8">
              Are you sure you want to delete this user? This action cannot be undone.
            </p>

            <div className="flex flex-col gap-3">
              <button
                onClick={handleDeleteUser}
                disabled={loading}
                className="w-full py-4 bg-red-500 text-white rounded-2xl text-sm font-black uppercase tracking-widest hover:bg-red-600 transition-all shadow-lg shadow-red-500/30 disabled:opacity-50"
              >
                Yes, Delete User
              </button>
              <button
                onClick={() => setDeleteModalUser(null)}
                disabled={loading}
                className="w-full py-4 bg-gray-50 text-gray-600 rounded-2xl text-sm font-black uppercase tracking-widest hover:bg-gray-100 transition-all disabled:opacity-50"
              >
                Cancel
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  )
}

export default AdminUsers

import { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import { FiTruck, FiRefreshCw, FiPhone, FiMapPin, FiPackage, FiShoppingBag, FiCheck, FiX } from 'react-icons/fi'
import toast from 'react-hot-toast'
import axiosInstance from '../../api/axiosInstance'

const AdminVendors = () => {
  const [vendors,  setVendors]  = useState([])
  const [loading,  setLoading]  = useState(true)

  useEffect(() => { fetchVendors() }, [])

  const fetchVendors = async () => {
    setLoading(true)
    try {
      const res = await axiosInstance.get('/admin/vendors')
      setVendors(res.data.vendors)
    } catch {
      toast.error('Failed to load vendors')
    } finally {
      setLoading(false)
    }
  }

  const approveVendor = async (id) => {
    try {
      await axiosInstance.put(`/admin/vendors/${id}/approve`)
      toast.success('Vendor approved!')
      fetchVendors()
    } catch {
      toast.error('Failed to approve vendor')
    }
  }

  const rejectVendor = async (id) => {
    try {
      await axiosInstance.put(`/admin/vendors/${id}/reject`)
      toast.success('Vendor rejected')
      fetchVendors()
    } catch {
      toast.error('Failed to reject vendor')
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="bg-white px-4 py-2 rounded-xl shadow-soft border border-gray-50 flex items-center gap-2">
          <FiTruck className="text-primary" />
          <p className="text-sm font-bold text-dark">{vendors.length} <span className="text-gray-400 font-medium">Partner Vendors</span></p>
        </div>
        <button 
          onClick={fetchVendors} 
          className="flex items-center gap-2 px-4 py-2 bg-white text-gray-500 hover:text-primary rounded-xl shadow-soft border border-gray-50 transition-all active:scale-95 text-sm font-bold"
        >
          <FiRefreshCw className={loading ? 'animate-spin' : ''} />
          Refresh
        </button>
      </div>

      {loading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {[1,2,3,4].map(i => <div key={i} className="bg-white rounded-3xl h-48 animate-pulse border border-gray-50 shadow-soft" />)}
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {vendors.map((vendor, i) => (
            <motion.div 
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.1 }}
              key={vendor._id} 
              className="bg-white rounded-3xl p-6 shadow-soft border border-gray-50 hover:shadow-medium transition-all group relative overflow-hidden"
            >
              <div className="flex items-start justify-between mb-6 relative z-10">
                <div className="flex items-center gap-4">
                  <div className="w-14 h-14 bg-orange-50 rounded-2xl flex items-center justify-center text-3xl shadow-sm border border-orange-100 group-hover:scale-110 transition-transform">
                    🏪
                  </div>
                  <div>
                    <h3 className="font-black text-dark text-lg leading-tight tracking-tight">{vendor.storeName}</h3>
                    <div className="flex items-center gap-2 mt-1">
                      <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{vendor.user?.email}</p>
                      {vendor.isMissingProfile && (
                        <span className="bg-amber-100 text-amber-600 text-[8px] font-black uppercase px-1.5 py-0.5 rounded-md border border-amber-200">Incomplete</span>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3 mb-6 relative z-10">
                <div className="flex items-center gap-2 text-[11px] font-bold text-gray-500 bg-gray-50 p-2 rounded-xl border border-gray-100">
                  <FiPhone className="text-primary" />
                  {vendor.phone}
                </div>
                <div className="flex items-center gap-2 text-[11px] font-bold text-gray-500 bg-gray-50 p-2 rounded-xl border border-gray-100">
                  <FiMapPin className="text-primary" />
                  {vendor.address?.city}
                </div>
                <div className="flex items-center gap-2 text-[11px] font-bold text-gray-500 bg-gray-50 p-2 rounded-xl border border-gray-100">
                  <FiPackage className="text-primary" />
                  {vendor.products?.length || 0} Prods
                </div>
                <div className="flex items-center gap-2 text-[11px] font-bold text-gray-500 bg-gray-50 p-2 rounded-xl border border-gray-100">
                  <FiShoppingBag className="text-primary" />
                  {vendor.totalOrders} Orders
                </div>
              </div>

              <div className="flex gap-3 relative z-10">
                {!vendor.isApproved ? (
                  <button
                    onClick={() => approveVendor(vendor._id)}
                    disabled={vendor.isMissingProfile}
                    className="flex-1 flex items-center justify-center gap-2 bg-emerald-500 text-white py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 shadow-glow transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <FiCheck />
                    {vendor.isMissingProfile ? 'Profile Required' : 'Approve'}
                  </button>
                ) : (
                  <button
                    onClick={() => rejectVendor(vendor._id)}
                    className="flex-1 flex items-center justify-center gap-2 bg-red-50 text-red-500 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all active:scale-95 border border-red-100"
                  >
                    <FiX />
                    Revoke Access
                  </button>
                )}
              </div>
              
              <div className="absolute -bottom-4 -right-4 text-gray-50/50 -rotate-12 pointer-events-none group-hover:rotate-0 transition-transform duration-700">
                <FiTruck size={100} />
              </div>
            </motion.div>
          ))}
          {vendors.length === 0 && (
            <div className="col-span-full text-center py-20 bg-gray-50/30 rounded-3xl border-2 border-dashed border-gray-100">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-300">
                <FiTruck size={40} />
              </div>
              <h4 className="text-dark font-bold">No partner vendors</h4>
              <p className="text-gray-400 text-xs mt-1">New applications will appear here</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default AdminVendors

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { FiShoppingBag, FiClock, FiCheckCircle, FiTruck, FiXCircle, FiMoreVertical, FiRefreshCcw } from 'react-icons/fi'
import toast from 'react-hot-toast'
import axiosInstance from '../../api/axiosInstance'

const statusColors = {
  placed:           'bg-blue-50 text-blue-600 border-blue-100',
  confirmed:        'bg-yellow-50 text-yellow-600 border-yellow-100',
  preparing:        'bg-orange-50 text-orange-600 border-orange-100',
  out_for_delivery: 'bg-purple-50 text-purple-600 border-purple-100',
  delivered:        'bg-green-50 text-green-600 border-green-100',
  cancelled:        'bg-red-50 text-red-500 border-red-100',
}

const VendorOrders = () => {
  const [orders,  setOrders]  = useState([])
  const [loading, setLoading] = useState(true)
  const [updating, setUpdating] = useState(null)

  useEffect(() => { fetchOrders() }, [])

  const fetchOrders = async () => {
    setLoading(true)
    try {
      const res = await axiosInstance.get('/orders/vendor-orders')
      setOrders(res.data.orders || [])
    } catch {
      toast.error('Failed to load orders')
    } finally {
      setLoading(false)
    }
  }

  const updateStatus = async (orderId, status) => {
    setUpdating(orderId)
    try {
      await axiosInstance.put(`/orders/${orderId}/status`, { status })
      toast.success(`Order ${status.replace('_', ' ')} successfully!`)
      fetchOrders()
    } catch {
      toast.error('Failed to update status')
    } finally {
      setUpdating(null)
    }
  }

  const formatDate = d => new Date(d).toLocaleDateString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit'
  })

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-black text-dark tracking-tight">Order Management</h2>
          <p className="text-gray-500 text-xs font-medium">Handle your customer orders and tracking</p>
        </div>
        <button 
          onClick={fetchOrders} 
          className="p-2.5 bg-white border border-gray-100 rounded-xl text-primary hover:bg-orange-50 transition-all shadow-sm active:scale-90"
        >
          <FiRefreshCcw className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      {loading ? (
        <div className="space-y-4">
          {[1,2,3].map(i => (
            <div key={i} className="bg-white rounded-[2rem] h-32 animate-pulse border border-gray-50" />
          ))}
        </div>
      ) : orders.length === 0 ? (
        <div className="bg-white rounded-[3rem] p-20 text-center shadow-soft border border-gray-50">
          <div className="text-7xl mb-6 grayscale opacity-20">📦</div>
          <h3 className="text-2xl font-black text-dark mb-2 italic font-serif">No orders yet</h3>
          <p className="text-gray-500 text-sm max-w-xs mx-auto">When customers fall in love with your flavors, their orders will appear here!</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {orders.map((order, i) => (
            <motion.div 
              key={order._id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
              className="bg-white rounded-[2.5rem] p-6 shadow-soft border border-gray-50 hover:shadow-medium transition-all group relative overflow-hidden"
            >
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
                <div className="flex items-center gap-4">
                  <div className="w-14 h-14 bg-orange-50 rounded-2xl flex items-center justify-center text-primary text-2xl shadow-sm group-hover:scale-110 transition-transform">
                    <FiShoppingBag />
                  </div>
                  <div>
                    <p className="font-black text-dark text-lg tracking-tighter">
                      #{order._id.slice(-8).toUpperCase()}
                    </p>
                    <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">
                      {order.user?.name} • {formatDate(order.createdAt)}
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap items-center gap-3">
                  <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border shadow-sm ${statusColors[order.orderStatus]}`}>
                    {order.orderStatus.replace('_', ' ')}
                  </div>
                  <p className="text-2xl font-black text-primary tracking-tighter">₹{order.totalAmount}</p>
                </div>
              </div>

              <div className="mt-6 flex flex-wrap gap-2">
                {order.items?.map((item, idx) => (
                  <div key={idx} className="bg-gray-50 border border-gray-100 px-4 py-2 rounded-2xl flex items-center gap-2">
                    <span className="text-xs font-bold text-dark">{item.name}</span>
                    <span className="text-[10px] bg-white px-2 py-0.5 rounded-md border border-gray-100 font-black text-primary">x{item.quantity}</span>
                  </div>
                ))}
              </div>

              <div className="mt-6 pt-6 border-t border-gray-50 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="flex items-center gap-4 text-xs font-bold text-gray-400 uppercase tracking-tighter">
                  <span className="flex items-center gap-1"><FiTruck /> {order.deliveryAddress?.city}</span>
                  <span className="flex items-center gap-1 font-black text-primary/60">💵 {order.paymentMethod}</span>
                </div>

                <div className="flex items-center gap-2">
                  {order.orderStatus === 'placed' && (
                    <button 
                      onClick={() => updateStatus(order._id, 'confirmed')}
                      disabled={updating === order._id}
                      className="px-6 py-2.5 bg-blue-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 transition-all shadow-soft active:scale-95 disabled:opacity-50"
                    >
                      Confirm Order
                    </button>
                  )}
                  {order.orderStatus === 'confirmed' && (
                    <button 
                      onClick={() => updateStatus(order._id, 'preparing')}
                      disabled={updating === order._id}
                      className="px-6 py-2.5 bg-orange-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-orange-600 transition-all shadow-soft active:scale-95 disabled:opacity-50"
                    >
                      Start Preparing
                    </button>
                  )}
                  {order.orderStatus === 'preparing' && (
                    <button 
                      onClick={() => updateStatus(order._id, 'out_for_delivery')}
                      disabled={updating === order._id}
                      className="px-6 py-2.5 bg-purple-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-purple-600 transition-all shadow-soft active:scale-95 disabled:opacity-50"
                    >
                      Out for Delivery
                    </button>
                  )}
                  {order.orderStatus === 'out_for_delivery' && (
                    <button 
                      onClick={() => updateStatus(order._id, 'delivered')}
                      disabled={updating === order._id}
                      className="px-6 py-2.5 bg-emerald-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-soft active:scale-95 disabled:opacity-50"
                    >
                      Mark Delivered
                    </button>
                  )}
                  {['placed', 'confirmed'].includes(order.orderStatus) && (
                    <button 
                      onClick={() => updateStatus(order._id, 'cancelled')}
                      disabled={updating === order._id}
                      className="p-2.5 bg-red-50 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all shadow-soft active:scale-95 disabled:opacity-50"
                    >
                      <FiXCircle size={18} />
                    </button>
                  )}
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  )
}

export default VendorOrders

